// Speech helpers for voice mode. Listening uses the browser's SpeechRecognition (speech -> text;
// where the browser lacks it, voice mode isn't offered). Speaking uses either the device's own
// voices (speechSynthesis) or Piper voices generated by our server (/Assistant/api/tts), chosen in
// Settings and saved per browser.

const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
const VOICE_KEY = "voiceURI";
const ENGINE_KEY = "voiceEngine"; // "device" or "piper"
const PIPER_KEY = "piperVoice";

export const recognitionSupported = Boolean(Recognition);
export const synthesisSupported = "speechSynthesis" in window;

// Listens for one utterance; the browser stops by itself after a pause. Calls onInterim with the
// words so far and onStage with what the mic is doing ("mic on" -> "hearing sound" -> "hearing
// speech", which shows where it gets stuck), then resolves with the text ("" if nothing was said).
// Gives up after SILENCE_MS without any words. stop() ends it early.
const SILENCE_MS = 10000;

export function listen(onInterim, onStage) {
  const recognition = new Recognition();
  recognition.lang = navigator.language || "en-US";
  recognition.interimResults = true;
  recognition.continuous = false;
  recognition.maxAlternatives = 1;
  let finalText = "";
  let latest = ""; // final + interim words so far
  const stage = (name) => {
    console.debug("[speech]", name);
    onStage?.(name);
  };
  let silence = setTimeout(() => recognition.stop(), SILENCE_MS);
  const done = new Promise((resolve, reject) => {
    recognition.onstart = () => stage("mic on, waiting for sound");
    recognition.onsoundstart = () => stage("hearing sound");
    recognition.onspeechstart = () => stage("hearing speech");
    recognition.onresult = (event) => {
      clearTimeout(silence);
      silence = null;
      let interim = "";
      finalText = "";
      for (const result of event.results) {
        if (result.isFinal) finalText += result[0].transcript;
        else interim += result[0].transcript;
      }
      latest = (finalText + interim).trim();
      onInterim?.(latest);
    };
    recognition.onerror = (event) => {
      stage(`error: ${event.error}`);
      // "no-speech" and "aborted" just mean nothing was said, or we stopped it
      if (event.error === "no-speech" || event.error === "aborted") resolve("");
      else reject(new Error(errorMessage(event.error)));
    };
    recognition.onend = () => {
      clearTimeout(silence);
      stage("ended");
      // Safari sometimes ends without marking anything final: use the last words it heard
      resolve(finalText.trim() || latest);
    };
  });
  recognition.start();
  return { done, stop: () => recognition.stop(), abort: () => recognition.abort() };
}

function errorMessage(code) {
  if (code === "not-allowed" || code === "service-not-allowed") {
    return "Microphone or speech recognition isn't allowed. On iPhone, turn on Siri & Dictation and allow the microphone.";
  }
  if (code === "network") return "Speech recognition needs an internet connection.";
  if (code === "audio-capture") return "No microphone was found.";
  return `Speech recognition failed (${code}).`;
}

// Turns a Markdown reply into something pleasant to hear. Voice-mode replies are asked to be plain
// already, but tool results and older habits can still produce tables, code, or links.
export function speakable(markdown) {
  return markdown
    .replace(/```[\s\S]*?```/g, " (I've put the code in the chat.) ")
    .replace(/(^\|.*\|\s*$\n?)+/gm, " (The table is in the chat.) ")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/https?:\/\/\S+/g, "a link in the chat")
    .replace(/<[^>]+>/g, " ")
    .replace(/[*_`#>~]+/g, "")
    .replace(/^\s*[-•]\s+/gm, "")
    .replace(/\s+/g, " ")
    .trim();
}

export function englishVoices() {
  if (!synthesisSupported) return [];
  return speechSynthesis.getVoices().filter((v) => v.lang.toLowerCase().startsWith("en"));
}

function load(key) {
  try {
    return localStorage.getItem(key) || "";
  } catch {
    return "";
  }
}

function store(key, value) {
  try {
    if (value) localStorage.setItem(key, value);
    else localStorage.removeItem(key);
  } catch {
    // Storage unavailable (private mode): the choice just won't persist
  }
}

export const savedVoiceURI = () => load(VOICE_KEY);
export const saveVoiceURI = (uri) => store(VOICE_KEY, uri);
export const savedEngine = () => (load(ENGINE_KEY) === "piper" ? "piper" : "device");
export const saveEngine = (engine) => store(ENGINE_KEY, engine === "piper" ? "piper" : "");
export const savedPiperVoice = () => load(PIPER_KEY);
export const savePiperVoice = (id) => store(PIPER_KEY, id);

// Piper voices installed on the server: [{ id, name }]
export async function piperVoices() {
  const res = await fetch("/Assistant/api/tts/voices");
  if (!res.ok) throw new Error(`Couldn't load server voices (${res.status})`);
  return (await res.json()).voices;
}

// The saved voice, else a British male voice for the Jarvis feel, else the browser default
function pickVoice() {
  const voices = englishVoices();
  const saved = savedVoiceURI();
  return (
    voices.find((v) => v.voiceURI === saved) ||
    voices.find((v) => /daniel|arthur|oliver|george/i.test(v.name) && v.lang === "en-GB") ||
    voices.find((v) => v.lang === "en-GB") ||
    null
  );
}

// Browsers load voices asynchronously, so getVoices() can be empty at first. Choosing a voice then
// falls back to the system default, and the next reply (voices loaded) switches to another voice
// mid-conversation. Wait for the list first (briefly; some browsers never fire the event).
let voicesReady = null;
function loadVoices() {
  if (!synthesisSupported || speechSynthesis.getVoices().length) return Promise.resolve();
  voicesReady ??= new Promise((resolve) => {
    const done = () => {
      speechSynthesis.removeEventListener("voiceschanged", done);
      resolve();
    };
    speechSynthesis.addEventListener("voiceschanged", done);
    setTimeout(done, 1500);
  });
  return voicesReady;
}
loadVoices();

// One audio element for Piper speech. iOS only plays audio started by a tap, but an element that
// has played once (the silent clip in unlockSpeech) may play again later without one.
const player = typeof Audio !== "undefined" ? new Audio() : null;
const SILENT_WAV = "data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=";
let finishPlayback = null; // resolves the current Piper speak() promise

// iOS only lets a page speak after a user gesture: call this from the tap that opens voice mode.
// Only the chosen voice source is unlocked, and audioSettled() waits for that silent clip to finish:
// starting the mic while audio plays can leave iOS recognition "on" but hearing nothing.
let unlocking = Promise.resolve();

export function unlockSpeech(engine = savedEngine()) {
  unlocking = new Promise((resolve) => {
    setTimeout(resolve, 600); // in case neither finishes cleanly
    if (engine === "piper" && player) {
      player.onended = () => resolve();
      player.src = SILENT_WAV;
      player.play().catch(() => resolve());
    } else if (synthesisSupported) {
      const silent = new SpeechSynthesisUtterance(" ");
      silent.volume = 0;
      silent.onend = () => resolve();
      silent.onerror = () => resolve();
      speechSynthesis.speak(silent);
    } else {
      resolve();
    }
  });
}

// Resolves once unlock audio has finished, plus a short pause so iOS can switch the audio
// session from playing back to recording
export async function audioSettled() {
  await unlocking;
  await new Promise((resolve) => setTimeout(resolve, 250));
}

// Speaks the text with the voice chosen in Settings, or the given override; resolves when it
// finishes or is stopped. Piper failures (server down, voice removed) fall back to a device voice.
export async function speak(text, { engine = savedEngine(), voiceURI, piperVoice = savedPiperVoice() } = {}) {
  if (!text) return;
  if (engine === "piper" && piperVoice && player) {
    try {
      return await speakWithPiper(text, piperVoice);
    } catch (e) {
      console.warn("Piper speech failed; using a device voice instead:", e);
    }
  }
  return speakOnDevice(text, voiceURI);
}

async function speakWithPiper(text, voice) {
  const res = await fetch("/Assistant/api/tts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text: text.slice(0, 3000), voice }),
  });
  if (!res.ok) throw new Error(`server speech failed (${res.status})`);
  const url = URL.createObjectURL(await res.blob());
  try {
    await new Promise((resolve, reject) => {
      finishPlayback = resolve;
      player.onended = () => resolve();
      player.onerror = () => reject(new Error("audio playback failed"));
      player.src = url;
      player.play().catch(reject);
    });
  } finally {
    finishPlayback = null;
    URL.revokeObjectURL(url);
  }
}

async function speakOnDevice(text, voiceURI) {
  if (!synthesisSupported) return;
  await loadVoices();
  return new Promise((resolve) => {
    speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const voice = voiceURI ? englishVoices().find((v) => v.voiceURI === voiceURI) : pickVoice();
    if (voice) {
      utterance.voice = voice;
      utterance.lang = voice.lang;
    }
    utterance.rate = 1.05;
    utterance.onend = () => resolve();
    utterance.onerror = () => resolve();
    speechSynthesis.speak(utterance);
  });
}

export function stopSpeaking() {
  if (synthesisSupported) speechSynthesis.cancel();
  if (player && !player.paused) player.pause();
  finishPlayback?.(); // pausing doesn't fire "ended", so finish the pending speak() ourselves
}
